    for role in order:
        log = OUT / f'{len(rows):02d}-r{rnd}-{clip}-{role}.log'
        bench = f'BenchmarkPublicDecoderFullClip/{clip}/warm_reset_decode'
        cmd = ['/Users/thesyncim/.codex/bin/project-env', PATHS[role], '-test.run=^$', f'-test.bench=^{bench}$', '-test.benchtime=20x', '-test.count=1', '-test.benchmem']
