 	return v.Shift(sh)
 }

+// Keep the two fixed rounding counts outside the row loop. ShiftAllRight
+// materializes its NEON count vector at each use with this compiler.
+func cdefRoundSign(v archsimd.Int16x8, sh cdefShiftCount) archsimd.Int16x8 {
+	return v.Shift(sh)
+}
+
+func cdefRoundScale(v archsimd.Int16x8, sh cdefShiftCount) archsimd.Int16x8 {
+	return v.Shift(sh)
+}
